bool id_present(const std::vector<int> &v, int id) {
    int lo = 0, hi = (int)v.size() - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (v[mid] == id) return true;
        if (v[mid] < id) lo = mid + 1;
        else hi = mid - 1;
    }
    return false;
}

