long long floor_root(long long n) {
    long long lo = 1, hi = 1000000000;
    while (lo < hi) {
        long long mid = lo + (hi - lo + 1) / 2;
        if (mid * mid <= n) lo = mid;
        else hi = mid - 1;
    }
    return lo;
}

int main() {
    long long n;
    std::cin >> n;
    std::cout << floor_root(n) << std::endl;
    return 0;
}

