int rotated_search(const std::vector<int> &v, int target) {
    int lo = 0, hi = (int)v.size() - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (v[mid] == target) return mid;
        if (v[lo] <= v[mid]) {
            if (target >= v[lo] && target < v[mid]) hi = mid - 1;
            else lo = mid + 1;
        } else {
            if (target > v[mid] && target <= v[hi]) lo = mid + 1;
            else hi = mid - 1;
        }
    }
    return -1;
}

